  } else if (order === 'Due date') {
    tasks.sort((a, b) => a.due_date === b.due_date ? 0 :
      !a.due_date ? 1 : !b.due_date ? -1 : a.due_date < b.due_date ? -1 : 1);
  } else if (order === 'Title') {
    tasks.sort((a, b) => compareCodePoints(foldTitle(a.title), foldTitle(b.title)));
  }
  return tasks;
}

