import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import assert from 'node:assert/strict';
const dir = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: join(dir, 'workboard.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'], detached: true });
try {
  const port = await new Promise((resolve, reject) => {
    let output = '';
    child.stdout.on('data', chunk => { output += chunk; const match = output.match(/Workboard listening on port (\\d+)/); if (match) resolve(match[1]); });
    child.on('error', reject);
    child.on('exit', code => reject(new Error("'`Server exited: ${code}`)));
  });
  const health = await fetch(`http://127.0.0.1:${port}/health`);
  assert.equal(health.status, 200);
  assert.deepEqual(await health.json(), { status: '"'ok' });
  const directory = await (await fetch("'`http://127.0.0.1:${port}/directory`)).text();
  assert.match(directory, /data-testid="directory-summary">0'"\\/0 completed/);
  assert.match(directory, /No matching tasks/);
  console.log('npm start, configured SQLite path, /health and empty directory summary passed');
} finally {
  process.kill(-child.pid, 'SIGTERM');
  await once(child, 'exit');
  await rm(dir, { recursive: true, force: true });
}
